import sys, itertools
tok = open('G366.txt').read().split(); m = int(tok[0])
mul = [list(map(int, tok[1 + i*m:1 + (i+1)*m])) for i in range(m)]
inv = [r.index(0) for r in mul]
tk = open('../c5/deep/1_3-3-3.sg_366_2.best.edges').read().split()
n = int(tk[0]); E = [(int(tk[1+2*k]), int(tk[2+2*k])) for k in range((len(tk)-1)//2)]
print("n", n, "edges", len(E), "identity row ok", mul[0] == list(range(m)))
s = [int(x) for x in sys.argv[1:4]]   # stabiliser generators for the three B orbits (table indices)
def cosets(sj):
    H = {0}; frontier = [0]
    # subgroup generated by sj
    while frontier:
        new = []
        for h in frontier:
            y = mul[h][sj]
            if y not in H: H.add(y); new.append(y)
        frontier = new
    Hs = sorted(H)
    cid = [-1]*m; reps = []
    for g in range(m):
        if cid[g] < 0:
            k = len(reps); reps.append(g)
            for h in Hs: cid[mul[g][h]] = k
    return cid, reps, len(Hs)
off = [366, 488, 610]
labs = [cosets(x) for x in s]
print("coset counts", [len(l[1]) for l in labs], "orders", [l[2] for l in labs])
def vert_of(v):
    if v < 366: return ('A', v)
    for j in range(3):
        if v < off[j] + len(labs[j][1]): return ('B', j, v - off[j])
    raise
# edge check: is it a G-graph under left multiplication?
Es = set(frozenset(e) for e in E)
def map_v(g, v):
    if v < 366: return mul[g][v]
    for j in range(3):
        if v < off[j] + len(labs[j][1]):
            k = v - off[j]; rep = labs[j][1][k]
            return off[j] + labs[j][0][mul[g][rep]]
bad_inv = 0
gens = list(range(1, m))[:]
import random
random.seed(1)
tests = random.sample(range(1, m), 6)
for g in tests:
    ok = all(frozenset((map_v(g, u), map_v(g, w))) in Es for (u, w) in E)
    print("g", g, "invariant" if ok else "NOT invariant")
